# These providers have no server-side session state, so the full message history is
# encoded as JSON in the session_id field. 50 KB is a conservative safety net: it is
# well below typical LLM context windows and small enough that it does not bloat the
# HTTP response payload. Older turns are dropped first; the system message at index 0
# is always kept.
_MAX_SESSION_BYTES = 50 * 1024
_JSON_LIST_OVERHEAD_BYTES = 2
_JSON_LIST_SEPARATOR_BYTES = 2

_THINK_OPEN = "<think>"
_THINK_CLOSE = "</think>"


def _message_size_bytes(message: dict[str, Any]) -> int:
    return len(json.dumps(message).encode())


def _trim_session(messages: list[dict[str, Any]]) -> list[dict[str, Any]]:
    message_sizes = [_message_size_bytes(message) for message in messages]
    total_size = _JSON_LIST_OVERHEAD_BYTES + sum(message_sizes)
    if len(message_sizes) > 1:
        total_size += (len(message_sizes) - 1) * _JSON_LIST_SEPARATOR_BYTES

    while total_size > _MAX_SESSION_BYTES and len(messages) > 2:
        messages.pop(1)
        total_size -= message_sizes.pop(1) + _JSON_LIST_SEPARATOR_BYTES
    return messages


def _partial_tag_suffix_len(buf: str, tag: str) -> int:
    """Length of the longest suffix of ``buf`` that is a proper prefix of ``tag``."""
    for length in range(min(len(buf), len(tag) - 1), 0, -1):
        if buf[-length:] == tag[:length]:
            return length
    return 0


def _strip_think_blocks(buf: str, in_think: bool) -> tuple[str, str, bool]:
    """Strip ``<think>...</think>`` spans from a streaming text buffer.

    Returns a 3-tuple ``(emit, remaining, new_in_think)`` where ``emit`` is text safe
    to show users, ``remaining`` holds any partial open/close tag that must be re-fed
    with the next chunk, and ``new_in_think`` indicates whether the parser is inside a
    think block after processing ``buf``.
    """
    emit = ""
    i = 0
    while True:
        if in_think:
            idx = buf.find(_THINK_CLOSE, i)
            if idx == -1:
                remainder = buf[i:]
                plen = _partial_tag_suffix_len(remainder, _THINK_CLOSE)
                remaining = remainder[len(remainder) - plen :] if plen else ""
                return emit, remaining, True
            i = idx + len(_THINK_CLOSE)
            in_think = False
        else:
            idx = buf.find(_THINK_OPEN, i)
            if idx == -1:
                remainder = buf[i:]
                plen = _partial_tag_suffix_len(remainder, _THINK_OPEN)
                if plen:
                    emit += remainder[: len(remainder) - plen]
                    return emit, remainder[len(remainder) - plen :], False
                emit += remainder
                return emit, "", False
            emit += buf[i:idx]
            i = idx + len(_THINK_OPEN)
            in_think = True


def _merge_tool_call_chunk(acc: list[dict[str, Any]], chunk: dict[str, Any]) -> None:
    """Merge a streaming ``tool_calls`` delta ``chunk`` into ``acc`` in place.

    The first chunk for a given ``chunk["index"]`` copies ``id`` and ``function.name``;
    every chunk concatenates ``function.arguments`` to accumulate the full argument
    string. Parallel tool calls at different indexes are tracked independently.
    """
    index = chunk["index"]
    entry = next((e for e in acc if e["index"] == index), None)
    if entry is None:
        function = chunk.get("function") or {}
        entry = {
            "index": index,
            "id": chunk.get("id"),
            "function": {"name": function.get("name"), "arguments": ""},
        }
        acc.append(entry)

    function = chunk.get("function") or {}
    if arguments := function.get("arguments"):
        entry["function"]["arguments"] += arguments


